1	//! Declaration order for a union the checker answered.
2	//!
3	//! The checker builds a union's members sorted by kind, then by value, so `"sm" | "md" | "lg"` comes back as
4	//! `"lg" | "md" | "sm"`; the order the author wrote is not in its answer, and it is the order a Storybook control lists
5	//! its options in. Two sources give it back, and the merge picks between them (`declared_order` in the parent module):
6	//!
7	//! - **oxc's syntax** ([`in_written_order`]): the union the prop's declaration writes, read from the file the checker
8	//!   names (`crate::extractor::written`). It orders the top-level union only, and a member written as a name the file
9	//!   does not declare (an import) places nothing: the members it stands for keep their place after the placed ones.
10	//! - **the structural resolver** ([`in_declared_order`]): where the structural pass resolved the same union, its order
11	//!   is the declared one, nested unions included. It goes with the resolver (ADR 0026, S7e).
12	//!
13	//! Only a reorder is made: no member is added, dropped or changed. A union neither source orders keeps the checker's
14	//! order (by kind, then value): not alphabetical, and not marked.
15	
16	use crate::extractor::written::{MemberKind, WrittenMember};
17	use crate::types::output::{ObjectField, PropType};
18	
19	/// `checker` with the members of every union it shares with `declared` put in `declared`'s order.
20	pub(super) fn in_declared_order(checker: PropType, declared: &PropType) -> PropType {
21	    match (checker, declared) {
22	        (PropType::Union(members), PropType::Union(order)) => PropType::Union(reorder(members, order)),
23	        // A union of string literals the structural pass keeps as their values (`type Size = "sm" | "lg"`).
24	        (PropType::Union(members), PropType::LiteralUnion { members: values, .. }) => {
25	            let order: Vec<PropType> = values.iter().map(|value| PropType::StringLiteral(value.clone())).collect();
26	            PropType::Union(reorder(members, &order))
27	        }
28	        (PropType::Array(inner), PropType::Array(declared)) => {
29	            PropType::Array(Box::new(in_declared_order(*inner, declared)))
30	        }
31	        (PropType::Readonly(inner), PropType::Readonly(declared)) => {
32	            PropType::Readonly(Box::new(in_declared_order(*inner, declared)))
33	        }
34	        (PropType::Intersection(members), PropType::Intersection(declared)) if members.len() == declared.len() => {
35	            PropType::Intersection(zip_ordered(members, declared))
36	        }
37	        (PropType::Tuple(elements), PropType::Tuple(declared)) if elements.len() == declared.len() => PropType::Tuple(
38	            elements
39	                .into_iter()
40	                .zip(declared)
41	                .map(|(mut element, declared)| {
42	                    element.element_type = in_declared_order(element.element_type, &declared.element_type);
43	                    element
44	                })
45	                .collect(),
46	        ),
47	        (PropType::Object(fields), PropType::Object(declared)) => PropType::Object(ordered_fields(fields, declared)),
48	        (
49	            PropType::Function { type_params, params, return_type },
50	            PropType::Function { params: declared_params, return_type: declared_return, .. },
51	        ) if params.len() == declared_params.len() => PropType::Function {
52	            type_params,
53	            params: params
54	                .into_iter()
55	                .zip(declared_params)
56	                .map(|(mut param, declared)| {
57	                    param.param_type = in_declared_order(param.param_type, &declared.param_type);
58	                    param
59	                })
60	                .collect(),
61	            return_type: Box::new(in_declared_order(*return_type, declared_return)),
62	        },
63	        (other, _) => other,
64	    }
65	}
66	
67	/// Whether `declared`, the structural type, gives a place to any member of `checker`'s top-level union: then its order
68	/// is the declared one, whether or not it differs from the checker's.
69	pub(super) fn places_any(checker: &PropType, declared: &PropType) -> bool {
70	    let PropType::Union(members) = checker else { return false };
71	    match declared {
72	        PropType::Union(order) => members.iter().any(|member| position(member, order).is_some()),
73	        PropType::LiteralUnion { members: values, .. } => members.iter().any(|member| match member {
74	            PropType::StringLiteral(value) => values.contains(value),
75	            _ => false,
76	        }),
77	        _ => false,
78	    }
79	}
80	
81	/// How many of a union's members the written order placed.
82	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
83	pub(super) enum Placed {
84	    All,
85	    Some,
86	}
87	
88	/// `checker`'s union with the members `written` states put in its order, then the others in their order in `checker`.
89	/// A member is placed by the written member that states it (a literal, a keyword, a name it answers to), else by kind
90	/// when the written union has one member of that kind and the checker one unplaced member of it. `None` when `checker`
91	/// is not a union or `written` places none of its members.
92	pub(super) fn in_written_order(checker: &PropType, written: &[WrittenMember]) -> Option<(PropType, Placed)> {
93	    let PropType::Union(members) = checker else { return None };
94	    let mut places: Vec<Option<usize>> =
95	        members.iter().map(|member| written.iter().position(|candidate| states(candidate, member))).collect();
96	    for index in 0..members.len() {
97	        if places[index].is_some() {
98	            continue;
99	        }
100	        let Some(kind) = kind_of(&members[index]) else { continue };
101	        let unplaced_of_kind = members
102	            .iter()
103	            .zip(&places)
104	            .filter(|(member, place)| place.is_none() && kind_of(member) == Some(kind))
105	            .count();
106	        let mut slots = written.iter().enumerate().filter(|(_, candidate)| **candidate == WrittenMember::Kind(kind));
107	        if let (Some((slot, _)), None) = (slots.next(), slots.next())
108	            && unplaced_of_kind == 1
109	        {
110	            places[index] = Some(slot);
111	        }
112	    }
113	    if places.iter().all(Option::is_none) {
114	        return None;
115	    }
116	    let placed = if places.iter().all(Option::is_some) { Placed::All } else { Placed::Some };
117	    let (mut known, unknown): (Vec<_>, Vec<_>) =
118	        members.iter().cloned().zip(places).partition(|(_, place)| place.is_some());
119	    known.sort_by_key(|(_, place)| *place);
120	    Some((PropType::Union(known.into_iter().chain(unknown).map(|(member, _)| member).collect()), placed))
121	}
122	
123	/// Whether the written member `written` states the checker's member `member`.
124	fn states(written: &WrittenMember, member: &PropType) -> bool {
125	    match written {
126	        // `boolean` is `true | false` to the checker; the source may have written either.
127	        WrittenMember::Type(written) => {
128	            written == member || (*member == PropType::Boolean && matches!(written, PropType::BoolLiteral(_)))
129	        }
130	        WrittenMember::Name(name) => answers_to(member, name),
131	        WrittenMember::Kind(_) => false,
132	    }
133	}
134	
135	/// Whether the checker's member is the type the source names `written` (`React.ReactNode`, `Size.Small`), by the name
136	/// without the namespace it was written through: the checker names the declaration.
137	fn answers_to(member: &PropType, written: &str) -> bool {
138	    let bare = |name: &str| name.rsplit('.').next().unwrap_or(name).to_owned();
139	    let written_bare = bare(written);
140	    match member {
141	        PropType::Named { name, .. } | PropType::Recursive { name, .. } => bare(name) == written_bare,
142	        PropType::EnumMember { enum_name, member, .. } => {
143	            written.strip_suffix(member.as_str()).and_then(|head| head.strip_suffix('.')).map(bare)
144	                == Some(bare(enum_name))
145	        }
146	        PropType::Ref { name, .. } => *name == written_bare,
147	        PropType::ReactNode => {
148	            matches!(written_bare.as_str(), "ReactNode" | "ReactElement") || written == "JSX.Element"
149	        }
150	        PropType::CssProperties => written_bare == "CSSProperties",
151	        PropType::ElementType => written_bare == "ElementType",
152	        _ => false,
153	    }
154	}
155	
156	/// The kind a member written only by its kind has on the checker's side.
157	fn kind_of(member: &PropType) -> Option<MemberKind> {
158	    match member {
159	        PropType::Function { .. } => Some(MemberKind::Function),
160	        PropType::Callable { .. } => Some(MemberKind::Callable),
161	        PropType::Object(_) => Some(MemberKind::Object),
162	        PropType::Array(_) => Some(MemberKind::Array),
163	        PropType::Tuple(_) => Some(MemberKind::Tuple),
164	        PropType::Readonly(_) => Some(MemberKind::Readonly),
165	        PropType::Intersection(_) => Some(MemberKind::Intersection),
166	        PropType::TemplateLiteral(_) => Some(MemberKind::Template),
167	        _ => None,
168	    }
169	}
170	
171	fn zip_ordered(members: Vec<PropType>, declared: &[PropType]) -> Vec<PropType> {
172	    members.into_iter().zip(declared).map(|(member, declared)| in_declared_order(member, declared)).collect()
173	}
174	
175	fn ordered_fields(fields: Vec<ObjectField>, declared: &[ObjectField]) -> Vec<ObjectField> {
176	    fields
177	        .into_iter()
178	        .map(|mut field| {
179	            let counterpart = declared.iter().find(|candidate| {
180	                candidate.name == field.name && candidate.index_key.is_some() == field.index_key.is_some()
181	            });
182	            if let Some(counterpart) = counterpart {
183	                field.prop_type = in_declared_order(field.prop_type, &counterpart.prop_type);
184	            }
185	            field
186	        })
187	        .collect()
188	}
189	
190	/// The members the declaration also has, in its order, then the members it does not have, in the checker's order: the
191	/// checker's place for them is its sort, not the source's, and a member the structural pass dropped is most often the
192	/// `undefined` or `null` written last. Unchanged when the declaration has none of them.
193	fn reorder(members: Vec<PropType>, declared: &[PropType]) -> Vec<PropType> {
194	    let places: Vec<Option<usize>> = members.iter().map(|member| position(member, declared)).collect();
195	    if places.iter().all(Option::is_none) {
196	        return members;
197	    }
198	    let (mut known, unknown): (Vec<_>, Vec<_>) =
199	        members.into_iter().zip(places).partition(|(_, place)| place.is_some());
200	    known.sort_by_key(|(_, place)| *place);
201	    known.into_iter().chain(unknown).map(|(member, _)| member).collect()
202	}
203	
204	/// The place of the checker's `member` in the structural union `declared`.
205	fn position(member: &PropType, declared: &[PropType]) -> Option<usize> {
206	    let bare = |name: &str| name.rsplit('.').next().unwrap_or(name).to_owned();
207	    declared.iter().position(|candidate| candidate == member).or_else(|| match member {
208	        // `boolean` is `true | false` to the checker; the source may have written either.
209	        PropType::Boolean => declared.iter().position(|candidate| matches!(candidate, PropType::BoolLiteral(_))),
210	        // The source may name a type through a namespace (`React.Ref`); the checker names the declaration.
211	        PropType::Named { name, .. } => declared.iter().position(
212	            |candidate| matches!(candidate, PropType::Named { name: written, .. } if bare(written) == bare(name)),
213	        ),
214	        _ => None,
215	    })
216	}
