// Prop-by-prop diff of two `extract --json` outputs: every component and prop whose full content differs.
import { readFileSync } from 'node:fs'
import { flattenProps } from '../../caliper/.claude/worktrees/agent-abfb93bc8ad1f7ec3/apps/oracle/src/caliper-input.ts'

const [baseFile, newFile] = process.argv.slice(2)
const load = (file: string) => JSON.parse(readFileSync(file, 'utf8'))
const base = load(baseFile)
const next = load(newFile)

const propsOf = (out: any, key: string, component: any): Record<string, string> => {
  const ids = flattenProps(out, key, component)
  return Object.fromEntries(Object.entries(ids).map(([name, id]) => [name, JSON.stringify(out.props[id as string])]))
}

const keys = new Set([...Object.keys(base.components), ...Object.keys(next.components)])
let changed = 0
const byChange = new Map<string, string[]>()
for (const key of [...keys].toSorted()) {
  const a = base.components[key]
  const b = next.components[key]
  if (!a || !b) {
    console.log(`component ${key}: ${a ? 'removed' : 'added'}`)
    continue
  }
  const { props: _pa, ...restA } = a
  const { props: _pb, ...restB } = b
  if (JSON.stringify(restA) !== JSON.stringify(restB)) console.log(`component ${key}: fields other than props differ`)
  const pa = propsOf(base, key, a)
  const pb = propsOf(next, key, b)
  for (const name of new Set([...Object.keys(pa), ...Object.keys(pb)])) {
    if (pa[name] === pb[name]) continue
    changed++
    const before = pa[name] ? JSON.parse(pa[name]) : undefined
    const after = pb[name] ? JSON.parse(pb[name]) : undefined
    const what = `${JSON.stringify(before?.type)}\n      => ${JSON.stringify(after?.type)}${
      JSON.stringify({ ...before, type: 0 }) !== JSON.stringify({ ...after, type: 0 }) ? '  (+ non-type fields)' : ''
    }`
    byChange.set(what, [...(byChange.get(what) ?? []), `${key}.${name}`])
  }
}
console.log(`${changed} prop(s) differ, ${byChange.size} distinct change(s)`)
for (const [what, where] of byChange) {
  console.log(`- ${where.length}x e.g. ${where.slice(0, 4).join(', ')}`)
  console.log(`      ${what.slice(0, 1500)}`)
}
const diag = (out: any) => JSON.stringify(out.diagnostics)
if (diag(base) !== diag(next)) console.log('diagnostics differ')
if (JSON.stringify(base.enums) !== JSON.stringify(next.enums)) console.log('enums differ')

